'use client';

import * as React from 'react';
import {createComponent, type EventName} from '@lit/react';
import '@material/web/labs/gb/components/scaffold/md-gb-app-scaffold.js';
import '@material/web/labs/gb/components/scaffold/md-gb-pane-scaffold.js';
import {AppScaffoldElement} from '@material/web/labs/gb/components/scaffold/app-scaffold-element.js';
import {PaneScaffoldElement} from '@material/web/labs/gb/components/scaffold/pane-scaffold-element.js';
import type {NavigationChangeDetail} from '@material/web/labs/gb/components/scaffold/app-scaffold-element.js';
import type {PaneLayoutChangeDetail, PaneResizeDetail, WindowClassChangeDetail, WindowHeightClassChangeDetail} from '@material/web/labs/gb/components/scaffold/pane-scaffold-element.js';

/**
 * A Material Design app scaffold (bars, rails, FAB, snackbar). Wraps <md-gb-app-scaffold>.
 * Docs: https://material-web.dev/3.0/components/
 */
export const MdAppScaffold = createComponent({
  react: React,
  tagName: 'md-gb-app-scaffold',
  elementClass: AppScaffoldElement,
  events: {
    onNavigationChange: 'navigation-change' as EventName<CustomEvent<NavigationChangeDetail>>,
    onWindowClassChange: 'window-class-change' as EventName<CustomEvent<WindowClassChangeDetail>>,
    onWindowHeightClassChange: 'window-height-class-change' as EventName<CustomEvent<WindowHeightClassChangeDetail>>,
  },
});

export type MdAppScaffoldProps = React.ComponentProps<typeof MdAppScaffold>;

/**
 * A Material Design pane scaffold (list-detail, supporting pane, feed). Wraps <md-gb-pane-scaffold>.
 * Docs: https://material-web.dev/3.0/components/
 */
export const MdPaneScaffold = createComponent({
  react: React,
  tagName: 'md-gb-pane-scaffold',
  elementClass: PaneScaffoldElement,
  events: {
    onLevitateClose: 'levitate-close' as EventName<Event>,
    onPaneLayoutChange: 'pane-layout-change' as EventName<CustomEvent<PaneLayoutChangeDetail>>,
    onPaneResize: 'pane-resize' as EventName<CustomEvent<PaneResizeDetail>>,
    onWindowClassChange: 'window-class-change' as EventName<CustomEvent<WindowClassChangeDetail>>,
    onWindowHeightClassChange: 'window-height-class-change' as EventName<CustomEvent<WindowHeightClassChangeDetail>>,
  },
});

export type MdPaneScaffoldProps = React.ComponentProps<typeof MdPaneScaffold>;
